# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">DİL VE KALP AFETLERİ: SUİZAN, TECESSÜS, GIYBET VE İFTİRA (TDB.1.2.3)</text>\n  <rect x="20" y="42" width="322" height="175" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="181" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">1. SUİZAN VE TECESSÜS (HUCURÂT, 12)</text>\n  <text x="32" y="88" font-size="10.8" fill="#881337">• Suizan (Kötü Zan): Somut bilgi ve delil</text>\n  <text x="40" y="104" font-size="10.5" fill="#881337">olmadan insanlar hakkında kötü niyet beslemek.</text>\n  <text x="40" y="120" font-size="10.5" font-weight="bold" fill="#881337">⟶ Karşıtı: Hüsnüzan (İyi ve olumlu zan).</text>\n  <text x="32" y="146" font-size="10.8" fill="#881337">• Tecessüs (Kusur Araştırma): İnsanların gizli</text>\n  <text x="40" y="162" font-size="10.5" fill="#881337">hâllerini, özel hayatını ve ayıplarını kurcalamak.</text>\n  <text x="40" y="178" font-size="10.5" font-weight="bold" fill="#881337">⟶ Karşıtı: Mahremiyete saygı ve Setr-i Uyûb.</text>\n  <rect x="358" y="42" width="322" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="519" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. GIYBET, İFTİRA VE NEMÎME</text>\n  <text x="370" y="88" font-size="10.8" fill="#78350f">• Gıybet (Dedikodu): Kişinin arkasından, var olan</text>\n  <text x="378" y="104" font-size="10.5" fill="#78350f">kusurunu konuşmak (ölü kardeş eti yemek gibi).</text>\n  <text x="370" y="128" font-size="10.8" fill="#78350f">• İftira (Bühtan): Kişide OLMAYAN bir kusuru</text>\n  <text x="378" y="144" font-size="10.5" fill="#78350f">veya suçu ona uydurarak isnat etmek.</text>\n  <text x="370" y="168" font-size="10.8" fill="#78350f">• Nemîme (Koğuculuk): İnsanların arasını</text>\n  <text x="378" y="184" font-size="10.5" fill="#78350f">bozmak amacıyla söz taşımak.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hadis Ölçüsü: "Söylediğin kusur kardeşinde varsa gıybet etmiş olursun; yoksa ona iftira etmiş olursun!" (Müslim)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">KALP HASTALIKLARI: HASET (KISKANÇLIK), KİBİR VE ALAY ETME</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">HASET İLE GIPTA (İMRENME) FARKI</text>\n  <text x="35" y="88" font-size="10.8" fill="#581c87">• Haset (Kıskançlık / Çekememezlik):</text>\n  <text x="45" y="104" font-size="10.5" fill="#581c87">Başkasındaki nimetin ondan YOK OLMASINI</text>\n  <text x="45" y="120" font-size="10.5" fill="#581c87">istemek; ilahi taksime itirazdır (Felak, 5).</text>\n  <text x="35" y="146" font-size="10.8" font-weight="bold" fill="#581c87">• Gıpta (İmrenme — Meşru ve Güzel Tutum):</text>\n  <text x="45" y="162" font-size="10.5" fill="#581c87">Başkasındaki nimetin onda kalmasını dileyerek</text>\n  <text x="45" y="178" font-size="10.5" fill="#581c87">kendisine de benzerinin verilmesini istemek.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">KİBİR (BÜYÜKLENME) VE İSTİHZÂ (ALAY)</text>\n  <text x="370" y="88" font-size="10.8" fill="#1e3a8a">• Kibir (Tekebbür): Kendini üstün görerek</text>\n  <text x="380" y="104" font-size="10.5" fill="#1e3a8a">"hakkı inkâr etmek ve insanları küçümsemek".</text>\n  <text x="380" y="120" font-size="10.5" font-weight="bold" fill="#1e3a8a">⟶ Karşıtı: Tevazu (Alçakgönüllülük).</text>\n  <text x="370" y="146" font-size="10.8" fill="#1e3a8a">• Alay Etme (İstihzâ) ve Kötü Lakap Takma:</text>\n  <text x="380" y="162" font-size="10.5" fill="#1e3a8a">İnsanları küçük düşürmek ve onurunu kırmak</text>\n  <text x="380" y="178" font-size="10.5" fill="#1e3a8a">Hucurât suresi 11. ayetle kesin yasaklanmıştır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hadis-i Şerif: "Ateşin odunu yiyip bitirdiği gibi haset de iyilikleri (hasenatı) yer bitirir." (Ebû Dâvûd, Edeb, 44)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BİRLİKTE YAŞAMA AHLAKI VE TOPLUMSAL HUZURU KORUYAN İLKELER</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">TOPLUMSAL BARIŞI KURAN DEĞERLER</text>\n  <text x="35" y="88" font-size="10.8" fill="#064e3b">• 1. Kardeşlik (Uhuvvet) ve Islah (Hucurât, 10)</text>\n  <text x="35" y="110" font-size="10.8" fill="#064e3b">• 2. Sıdk (Doğruluk) ve Emanet (Güvenilirlik)</text>\n  <text x="35" y="132" font-size="10.8" fill="#064e3b">• 3. Adalet ve Hakkaniyet (Nisâ, 58; Mâide, 8)</text>\n  <text x="35" y="154" font-size="10.8" fill="#064e3b">• 4. Hüsnüzan, Affedicilik ve Tevazu</text>\n  <text x="35" y="176" font-size="10.8" fill="#064e3b">• 5. İnfak, Yardımlaşma ve Îsâr (Diğergamlık)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">KUL HAKKI VE HELALLEŞME BİLİNCİ</text>\n  <text x="370" y="88" font-size="10.8" fill="#7c2d12">• Gıybet, iftira, alay ve mal gaspı doğrudan</text>\n  <text x="380" y="104" font-size="10.8" font-weight="bold" fill="#7c2d12">"Kul Hakkı" ihlalidir.</text>\n  <text x="370" y="128" font-size="10.8" fill="#7c2d12">• Kul hakkının affı için yalnız Allah\'a tövbe</text>\n  <text x="380" y="144" font-size="10.5" fill="#7c2d12">etmek yetmez; mağdurun gönlünü almak,</text>\n  <text x="380" y="160" font-size="10.5" fill="#7c2d12">itibarını iade etmek ve dünyada iken</text>\n  <text x="380" y="176" font-size="10.5" font-weight="bold" fill="#7c2d12">helalleşmek şarttır (Müflis Hadisi).</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hadis: "Müslüman, diğer Müslümanların elinden ve dilinden güvende olduğu kimsedir." (Buhârî, Îmân, 4)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
